    getLog().info(String.format("%s: %d", INFO_DEPS_DISCOVERED, dependencies.size()));

    return artifacts;

    // tempting, but does not resolve dependencies after the scope in which this
    // plugin is invoked
    // return project.getArtifacts();
  }

